CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 NUMERIC DEFAULT 'd', c2 NUMERIC DEFAULT 'd', c3 BLOB, c4 VARCHAR(10));
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'b58f4f920c', 'psi', 255.68, 322, x'926036');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(329, x'8c930a763a', 717, NULL, NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 BLOB CHECK(c0 IS NULL OR length(c0) < 40), c1 INT, c2 TEXT);
INSERT OR IGNORE INTO t1(c0, c1, c2) VALUES(NULL, 'tau', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2) VALUES(-3, 1e-7, -269);
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', -1, 0), instr('omega', 'MU'), replace('omega', 'a', ''), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '_', 'omega' GLOB 'a*', char(79, 690), 'omega' || 'MU', 'omega' < 'MU', 'omega' = 'MU' COLLATE NOCASE;
SELECT length('日本'), upper('日本'), lower('日本'), substr('日本', -1, 4), instr('日本', '0x1F'), replace('日本', 'a', ''), trim('日本'), ltrim('日本', 'ab'), hex('日本'), quote('日本'), unicode('日本'), '日本' LIKE '%a_', '日本' GLOB 'a*', char(85, 808), '日本' || '0x1F', '日本' < '0x1F', '日本' = '0x1F' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 4, 4), instr('zeta', 'MU'), replace('zeta', '', 'XY'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '%é%', 'zeta' GLOB '*[a-m]*', char(78, 646), 'zeta' || 'MU', 'zeta' < 'MU', 'zeta' = 'MU' COLLATE NOCASE;
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', -1, 1), instr('0x1F', '42'), replace('0x1F', '', ''), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE '_', '0x1F' GLOB '*[a-m]*', char(77, 984), '0x1F' || '42', '0x1F' < '42', '0x1F' = '42' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', -3, 5), instr('nu', '0x1F'), replace('nu', '', '_'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '%', 'nu' GLOB '?', char(87, 222), 'nu' || '0x1F', 'nu' < '0x1F', 'nu' = '0x1F' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 2, 2), instr('Lambda', 'alpha'), replace('Lambda', 'é', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%', 'Lambda' GLOB 'a*', char(69, 898), 'Lambda' || 'alpha', 'Lambda' < 'alpha', 'Lambda' = 'alpha' COLLATE NOCASE;
SELECT a.id, b.id, a.c0, b.c0 FROM t1 a LEFT JOIN t1 b ON a.id >= b.id ORDER BY 1, 2 LIMIT 5;
SELECT count(*) FROM t1 a JOIN t1 b USING(id);
